quests[7701] = { id = 7701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Overseer Maltorius", description = "By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed.\n\nSee Lookout Captan Lolo Longstriker fer the reward on this bounty.", progress = "Can't ya shee I'm bushy? What *hic* ish it ya be wantin? *hic*", completion = "I never thunk I'd be lookin' at thish ugly mug again!\n\nHe acshually looksh better without the resht o' him attached.\n\nHere's yer reward *hic*, {race}.", objectives = "Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.\n\nSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7702] = { id = 7702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill 'Em With Sleep Deprivation", description = "If we want to put a dent in the productivity of the Dark Iron forces working out of the Slag Pit, we have to hit them where it's going to hurt the most.\n\nIt's a little known fact but dwarves, particularly of the Dark Iron variety, need rest! Lots of rest!\n\nNow I ask you; How can they sleep without pillows? Exactly, {name}, they can't. This is why you must weasel your way into the Slag Pit and steal their pillows.", progress = "Don't let the crazy goggles fool you, {name}. I'm the smart one here.", completion = "Wonderful! Those sleepy Dark Irons will head back to their homes in the Depths to get some rest, greatly slowing down the productivity of the Slag Pit.", objectives = "Deep within the Slag Pit of the Cauldron, you will find the sleeping quarters of the Dark Iron dwarves.\n\nTravel to the sleeping quarters and steal 20 Dark Iron Pillows. Return to Evonice Sootsmoker in the Searing Gorge when you have accomplished this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7703] = { id = 7703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Gordok Business", description = "Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!", progress = "Hah, you no find it, do you boss? Maybe old timey story a bad story... hard to believe that creepy elf can steal from Gordok king!", completion = "Wow... you ARE da true king! I never think I see this gauntlet in my life! It look like it got no mojo left anymore... maybe that creepy elf try and ruin gauntlet. Well, I say HAR HAR to him!\n\nLook - this mark on da gauntlet an old old OLD timey magic mark, older than da Gordok they say. Well, as Captain of da Gordok, we all learn one thing over and over - how to make mark come to life and give power back to gauntlet!\n\nI do it for you, king! Here, take da gauntlet and rule FOREVER!", objectives = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7704] = { id = 7704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look at the Size of It!", description = "Well, well, well... Isn't this a surprise. The Chambermaid had a gigantic ornate pillow and now it's yours. Evonice Sootsmoker will definitely want to get her grubby little hands all over this item. Take it to her and see if she'll offer you any goodies for your trouble.", progress = "That is one huge pillow! Where'd you get it from?", completion = "This is better than even I could have thought possible! The Chambermaid's magical pillow is mine! You better believe you're going to get a nice reward for this accomplishment, {name}!", objectives = "Take Chambermaid Pillaclencher's Pillow to Evonice Sootsmoker in the Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7721] = { id = 7721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel for the Zapping", description = "If I bet against my own better judgment and stay to run an engineering shop along the Forgotten Coast, I will need to deal with these pesky elementals.  Curse the powers of elementalism unchecked, I say!\n\nFortunately for me, and now for you my hopeful agent provocateur, the elementals represent an ideal source of raw power for my Ultra-Shrinker refinement - give them the what-for I say!  When doing this though, be sure to save me the water elemental cores!", progress = "While I could bore you with the technical details of the utility behind elemental cores, I will instead tempt you to completion of this important task by offering valuable coin and prizes for doing so.  Yon verily, are you finished?", completion = "Scrumdillyriffic!  These cores will keep me working for some time.  Add to that the benefit of there now being fewer elementals along the coast, and I might no longer cry myself to sleep at the prospect of having set up shop in perhaps the worst place imaginable!\n\nThank you, {name}, for your efforts on my behalf.  While it certainly straps me financially to do this, allow me to show you some gratitude you may understand and appreciate... loot!", objectives = "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7722] = { id = 7722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Flux?", description = "When that traitor, Maltorius, left our clan, he left with something more valuable than a pristine arcane crystal: Our recipe for fiery flux! I'd bet anything that the recipe was part of the deal in his new promotion amongst the Dark Irons.\n\nI want you to get our secret plans back, {name}. I'm sure they're somewhere near Maltorius, deep inside the Slag Pit.", progress = "Did you find the plans?", completion = "I hope you kicked his teeth in too, {name}. Ragnaros knows, he deserved it.\n\nNow we can get down to business.", objectives = "Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7723] = { id = 7723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse These Fat Fingers", description = "Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem. Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand. They're like gigantic Thelsamar Blood Sausages, they are...\n\nYe're gonna have to carry out me orders of business and what have ye.\n\nFirst on me agenda: Poundin' the livin' daylights out o' the heavy war golems o' the Gorge. Get crackin'.", completion = "Ye're a good lad, ye are. I got ye a lil' present fer yer troubles.", objectives = "Hansel Heavyhands wants you to kill 20 Heavy War Golems.\n\nThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7724] = { id = 7724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Menace!", description = "Wouldn't ye know it, every time ol' Hansel wants to take a moment to relax and reflect upon his life, the powers that be give him another job.\n\nMe gots to think, come on! Ye know what I be saying? Come. On.\n\nSo, these here greater lava spiders are causin' a ruckus o' some sort. Oilfist says they shoot fire out their... erm, yea well, anyway, such things upset the children.\n\nI guess we gots to kill 'em. Rather, ye gots to kill 'em.", completion = "<Hansel sneezes.>\n\nI think I'm gettin' a cold. Damn this frigid climate!", objectives = "Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.\n\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7725] = { id = 7725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Again With the Zapped Giants", description = "I know you've gathered residue for me already... but should you find yourself for want of an encore performance to a fun-time activity, I can always use more residue.\n\nWhile I can't offer nearly as much in the way of compensation again, I'll be more than happy to spread the good word of your service to all my goblin friends with ears.\n\nBelieve me <sir/madam> when I say that these goblins have quite large ears.", progress = "Ah, the fruits of research and utilization in the form of sweet, sweet residue.  Well, that is to say, I don't taste it or anything when I study it.\n\nMuch.", completion = "Inconceivably fantastical, {name}!  You've come through for me again, and for that I thank you.\n\nThank you!\n\nWhile you may find this coin to be a little less than you're accustomed to, rest assured your great deeds on the field of goblindom are echoing through the halls of power in the Steamwheedle Cartel.  Should you need something else to do, then by all means talk to me!", objectives = "Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7726] = { id = 7726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Refuel for the Zapping", description = "More work, you say?  Did my heroic mission of collecting bits of goo found inside elemental beings not slake your thirst for adventure?  Perhaps more of the same will vainly try to fill the bottomless well of questing you possess...\n\nOK, melodrama aside, I do need more water elemental cores.  I'm trying desperately to set up shop here, so the rewards won't be as great... but I promise you I'll tell everyone in earshot how you've helped me.  Trust me on this - I know people in the Cartel!", progress = "Have you managed to find the elemental cores I need?", completion = "Top notch, {name}, top notch!  While the coin I give you might not be the most you'll ever receive for such work, rest assured my comrades in the Steamwheedle Cartel will hear about your efforts!\n\nIf you are looking for anything else to do, then let me know.  I can always use more elemental cores and such.", objectives = "Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7727] = { id = 7727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incendosaurs? Whateverosaur is More Like It", description = "Bunions, <lad/lass>. Me bunions got bunions. How am I supposed to do any sort of killin' with me feet in such disarray? That's why ye're gonna help.\n\nScrange and Burninate tasked me to kill these things so they can send some expeditionary teams down into the Slag Pit lava pools to do some explorin'. Supposedly some incendosaurs or some such nonsense down there causin' all kinds o' problems. Now move along an' don't come back 'til the incendosaur population be extinct.", completion = "Oh me achin' feets.\n\nI figured since ye didn't have a luffa...", objectives = "Hansel Heavyhands wants you to kill 20 Incendosaurs.\n\nYou will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.\n\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7728] = { id = 7728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "STOLEN: Smithing Tuyere and Lookout's Spyglass", description = "The following items have been stolen:\n\n*One Dark Iron Tuyere.\n\n*One Lookout's Spyglass.\n\nA reward is being offered to individuals who find and return these pilfered items.\n\nThe Thorium Brotherhood is certain that these items were stolen by unscrupulous and jealous Dark Iron dwarves that inhabit the Searing Gorge.\n\nThe spyglass in question was an excellent tool for the lookouts and the tuyere was an irreplaceable smithing tool.\n\nShould you find the missing items, return them to Scrange.", progress = "If you're here for the reward, you're gonna have to give me the stolen goods.", completion = "Fantastic work! Now for your reward.", objectives = "Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.\n\nThe only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7729] = { id = 7729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "JOB OPPORTUNITY: Culling the Competition", description = "Taskmaster Scrange is looking for a few good men and women to help 'cull the competition' in the Searing Gorge.\n\nIf you are interested in this position, venture out into the Searing Gorge and slaughter every Dark Iron Taskmaster and Dark Iron Slaver that you see.\n\nReturn to Taskmaster Scrange when your clothes are bloody enough.\n\nYou'll know when they're bloody enough so don't ask.", completion = "15.9 pounds! That may be a new record for blood and gut weight on apparel! Congratulations, {class}!", objectives = "Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7730] = { id = 7730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash Infestation", description = "From what scouting we have managed to muster, we believe that the foe south of the gnolls is an insect-like race.  Frankly, it is irrelevant whether or not if they're sentient.  If they are driving the gnolls to frenzy against us, then they are as big of a threat - if not more - than the gnolls.\n\nDrive deep into where these Zukk'ash insects dwell; it is known as the Writhing Deep.  Thin their numbers and report back to me what you find, bringing back their carapaces as evidence of your handiwork.", progress = "How goes the hunt, {name}?  Are you here to report your success?", completion = "Well done, {class}.  Though the extensiveness of the Zukk'ash presence will not be thwarted with anything less than a full-scale invasion, you have bought us some time so we can devise a proper strategy.\n\nI will be sure to have these carapaces analyzed; we'll need to learn everything about them before we deal with what has unfortunately turned into a much larger issue than we had anticipated.", objectives = "Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7731] = { id = 7731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinglasher", description = "In surveying the Writhing Deep, one of our scouts reported seeing a giant insect - much larger than the other insects spotted - wandering about the twisted terrain.  Not only is it larger, it also seems to secrete some sort of aura that the other insects don't.  We've given it a name - Stinglasher.\n\nThe innards of this beast would be invaluable to study as we figure out the best way to deal with this new threat.  Cut out its secretion glands and bring it back to me immediately!", progress = "Have you managed to bring down Stinglasher yet?", completion = "Impressive, {class}... most impressive!  If Stinglasher is indeed one of their strongest creatures, the study of the beast will prove to be quite valuable in time.  It's now my charge to make sure we defend ourselves long enough to take advantage of it.\n\nPlease accept this coin bounty as a token of the entire camp's thanks, {name}.  Well done.", objectives = "Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7732] = { id = 7732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash Report", description = "You've done doubly well in addressing the threat that the Zukk'ash insects pose to Camp Mojache.  The threat these things pose is far from over, and I'd like to ask you for one last task on behalf of the Horde.\n\nThis is a document that details all the information we have learned about these Zukk'ash insects.  I want you to deliver it to Zilzibin Drumlore in the Drag of Orgrimmar.  He's an expert on alien creatures like these; I hope he can do something with the lore we've obtained.", progress = "Greetings friend... you look as though you are on urgent business.  Is there something I can help you with?", completion = "Ah, I've been expecting this.  These creatures you faced... they are an ancient threat that the Horde continues to choose to ignore.  Hadoken was wise to bring this - and you - to me.\n\nThe Zukk'ash are nothing more than creatures called the silithid.  Some would think that they are a mindless nuisance, but let me assure you - they are a far, far worse threat than anything the Alliance could muster.\n\nIf you're willing and strong enough, I could use your aid in bringing this threat to light.", objectives = "Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore. He resides in the Drag of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7733] = { id = 7733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improved Quality", description = "I have a lead on an even BETTER source of hides, if that's even possible to believe!  In the northern parts of Feralas - deep within Rage Scar Hold - are another throng of yetis.  They're much tougher than the ones you dealt with before, so if you're up for a bigger challenge you'd best be on your toes!\n\nI would reward you handsomely for a stack of ten of their hides; bring them to me here, and we'll finish our business.", progress = "If these Rage Scar yeti hides are anything like the quality displayed by their Feral Scar counterparts, they could very well be as resilient as thorium!\n\nImagine that!", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your help {name}.  Here - please take one of my latest creations.", objectives = "Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7734] = { id = 7734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improved Quality", description = "I have a lead on an even BETTER source of hides, if that's even possible to believe!  In the northern parts of Feralas - deep within Rage Scar Hold - are another throng of yetis.  They're much tougher than the ones you dealt with before, so if you're up for a bigger challenge you'd best be on your toes!\n\nI would reward you handsomely for a stack of ten of their hides; bring them to me here, and we'll finish our business.", progress = "If these Rage Scar yeti hides are anything like the quality displayed by their Feral Scar counterparts, they could very well be as resilient as thorium!\n\nImagine that!", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your aid, {name}.  Here - please take one of my latest creations.", objectives = "Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7735] = { id = 7735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Yeti Hide", description = "You have found a pristine yeti hide that is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Pratt McGrubben at the Feathermoon Stronghold is in the market for yeti hides, this particular one may be of considerable interest to him.", progress = "What's this, {name} - you've got something special for me?", completion = "Incredible!  You may have found the granddaddy of all yeti hides with this!\n\nYou better believe I'll pay you for it.  I normally don't pay that much for a single hide, but I'm pretty sure I can make something special from it.  Thanks for thinking of me on this, {name}!", objectives = "Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7736] = { id = 7736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Fiery Flux Supplies via Kingsblood", progress = "Let's not waste more of my precious time with jibber jabber, {race}. It's time to focus on replenishing our dwindling fiery flux supply.\n\nWhat I'm gonna need from you is the following:\n\n*Incendosaur scales.\n\n*Kingsblood.\n\n*Coal.\n\nI'll take all that you can offer!\n\nAnd you'll do it fast if you wanna get in good with the Brotherhood.", completion = "There's always room for more fiery flux, junior. Keep it comin'... unless I tell you to stop." }
quests[7737] = { id = 7737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining Even More Acceptance", progress = "You've worked your way up through the Brotherhood's corporate hierarchy, {race}. We have begun to look favorably upon you. Quite an accomplishment!\n\nIf you're interested in more work and earning more respect amongst us, listen up.\n\nWe can refine our fiery flux by adding a simple Dark Iron residue to the mix. This Dark Iron residue can be found in Blackrock Depths.\n\nBring me all the Dark Iron residue you find!", completion = "Keep the residue pouring in!" }
quests[7738] = { id = 7738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfect Yeti Hide", description = "You have found what may very well be a perfect yeti hide.  You easily note that it is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Jangdor Swiftstrider at Camp Mojache is in the market for yeti hides, this particular one may be of considerable interest to him.", progress = "What's this, {name} - you've got something special for me?", completion = "This is an incredible find!  I believe this is the finest yeti hide specimen I have ever seen!\n\nIndeed, this is certainly worthy of an appropriate bounty.  I normally don't pay that much for a single hide, but I'm confident I can make something special from it.  Thanks for thinking of me on this, {name}!", objectives = "Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Camp Mojache, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7761] = { id = 7761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackhand's Command", description = "Imbecile,\n\nI hold very little faith in your ability to prevent outsiders from accessing the master's lair. In the very likely event of your death, this orb has its own failsafe built in to prevent outsiders from teleporting directly into Blackwing.\n\nOnly those with the Mark of Drakkisath branded upon their hand may make use of this orb. Thankfully, Drakkisath is not nearly as incompetent as you, Quartermaster. He guards the brand himself!\n\n-Warchief Rend Blackhand\n\nP.S. Destroy this letter, idiot.", completion = "You don't even flinch as the smoldering brand is pressed into your flesh. You are so tough!\n\nYou now hold the Mark of Drakkisath. Have fun storming the castle.", objectives = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\n\nThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7781] = { id = 7781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of Blackrock", description = "The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian. Bring it to the Grand Admiral on the King's behalf, champion.", progress = "Inconceivable!", completion = "You need not be told the meaning of what you have done, {name}. This day will be recorded in the annals of history. A victory the likes of which has not been known to the Alliance for years - if ever!", objectives = "Bring the Head of Nefarian to Grand Admiral Jes-Tereth in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7782] = { id = 7782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of Blackrock", description = "Go to the Valley of Heroes and speak with Field Marshal Stonebridge.", completion = "<Field Marshal Afrasiabi bows.>\n\nChoose your reward, let the celebration begin!", objectives = "Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Stonebridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7783] = { id = 7783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of Blackrock", description = "The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian. Return it to the Warchief's advisor Eitrigg, champion.", progress = "I wish I could have seen the look on the beast's face when you struck the killing blow!", completion = "Once more you have honored the Horde, {name}. The son of Deathwing is dead.\n\nSurely, the evil one stirs!", objectives = "Return the Head of Nefarian to Eitrigg in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7784] = { id = 7784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of Blackrock", description = "Seek out Overlord Natoj in the Valley of Strength.", completion = "Choose your reward, an' I gonna mount da head of da beast for all to see.", objectives = "Speak with Overlord Natoj in Orgrimmar. He stands waiting for you in the Valley of Strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7785] = { id = 7785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Examine the Vessel", description = "Examine the vessel of his rebirth, mortal. It is from this that the Windseeker shall be reborn!", progress = "Will you release him from his eternal prison?", completion = "May you be protected in your crusade. May the Master bless your efforts.", objectives = "Examine the Vessel of Rebirth and return it to Highlord Demitrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7786] = { id = 7786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderaan the Windseeker", description = "I have told you all that I know, {name}. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form.\n\nDo this and gain the blessing of Thunderaan.", progress = "Bring the world to its knees if you must!", completion = "Even in dreams I did not dare foresee this day.\n\nBehold, mortal.\n\nBEHOLD HE WHO IS OLDER THAN EXISTENCE!\n\nBEHOLD HE WHO HAS FACED TITAN AND GOD ALIKE!\n\nRISE MY MASTER! BREAK FROM YOUR BONDS!", objectives = "To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Enchanted Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7787] = { id = 7787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Thunderfury!", description = "You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch, Demitrian, to use the materials you provided for his betrayal to wake Thunderfury.", progress = "<Demitrian cowers in your presence.>", completion = "Please, do not harm me! Take it! Take the blade! Leave Demitrian to reshape his pathetic life!", objectives = "Present the Dormant Wind Kissed Blade to Highlord Demitrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7788] = { id = 7788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanquish the Invaders!", description = "Beyond this tunnel you will find a field of strife and turmoil, young {class}. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, {name}, and I shall reward you.", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7789] = { id = 7789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, {race}. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, {name}, and you will be rewarded.", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7790] = { id = 7790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Written Word", description = "Here's something you didn't expect...." }
quests[7791] = { id = 7791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Wool", progress = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Ironforge for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, {name}!" }
quests[7792] = { id = 7792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Wool", progress = "We are currently gathering wool. A donation of sixty pieces of wool cloth will net you full recognition by our people for your generous actions.\n\nIf you currently have sixty pieces, you may donate them now.", completion = "Our thanks for your donation, {name}." }
quests[7793] = { id = 7793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Silk", progress = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, {name}!" }
quests[7794] = { id = 7794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Mageweave", progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by Ironforge, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, {name}!" }
quests[7795] = { id = 7795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Runecloth", progress = "{name}, you've been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of runecloth, and we hope that you will be able to help us as you have in the past.\n\nIf you are willing, please bring me what runecloth you can spare. We'll initially accept a single donation of sixty, and then we'll go from there.", completion = "Fantastic - these will go right to use, I assure you. Thank you again for your assistance! We'd certainly be lost without you.\n\nWith all the donations you've made, I would certainly process any additional runecloth donations you care to make in the future. Just be sure to check in with me, and I'll personally make sure that your good deeds won't go unrecognized!" }
quests[7796] = { id = 7796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Additional Runecloth", progress = "Greetings once again, {name}! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of Stormwind.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", completion = "{name} - without heroes like you working on behalf of Stormwind, we'd surely suffer. Thank you for your continued efforts!" }
quests[7797] = { id = 7797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimensional Ripper - Everlook" }
quests[7798] = { id = 7798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Silk", progress = "We are currently gathering silk. A donation of sixty pieces of silk cloth will net you full recognition by our people for your generous actions\n\nIf you currently have sixty pieces, you may donate them now.", completion = "Our thanks for your donation, {name}." }
quests[7799] = { id = 7799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Mageweave", progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by Ironforge, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, {name}!" }
quests[7800] = { id = 7800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Runecloth", progress = "{name}, you've been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of runecloth, and we hope that you will be able to help us as you have in the past.\n\nIf you are willing, please bring me what runecloth you can spare. We'll initially accept a single donation of sixty, and then we'll go from there.", completion = "Fantastic - these will go right to use, I assure you. Thank you again for your assistance! We'd certainly be lost without you. With all the donations you've made, I would certainly process any additional runecloth donations you care to make in the future. Just be sure to check in with me, and I'll personally make sure that your good deeds won't go unrecognized!" }
quests[7801] = { id = 7801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Additional Runecloth", progress = "Greetings once again, {name}! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of Darnassus.\n\nWhenever you are ready to hand in the stack of runecloth, I'll accept it.", completion = "{name} - without heroes like you working on behalf of Darnassus, we'd surely suffer. Thank you for your continued efforts!" }
quests[7802] = { id = 7802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Wool", progress = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Ironforge for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, {name}!" }
