quests[7810] = { id = 7810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arena Master", description = "There must be more to being a master of the arena than this!\n\nPerhaps the Pirate who runs the event at Gurubashi will know!", completion = "Arr Me Hearty!   Gaining one Trinket be not enough to make ye master of the Arena!    Now tis the time to truly prove your steel.", objectives = "Speak with Short John Mithril in the Stranglethorn Arena.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
