quests[7814] = { id = 7814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Silk", progress = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, {name}!" }
quests[7815] = { id = 7815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snapjaws, Mon!", description = "Don't let their big eyes fool you, mon! Those saltwater snapjaws be a menace. I can't fish for five minutes without getting a broken line from one of those oversized fish vacuums stealing my bait.\n\nDo me and the people of Revantusk Village a service and kill em, mon.\n\nKill the whole lot of em!", completion = "Oh, mon! I can't thank you enough! Hopefully this here fishing pole will be reward enough for the job.", objectives = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 10 Saltwater Snapjaw turtles. Return to him when you have completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7816] = { id = 7816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gammerita, Mon!", description = "Yo! There be a turtle out there not like the others. She be the Gammerita, leader of the saltwater snapjaws - a downright dirty thievin' reptile.\n\nMon, she stole my best lure. Snapped it right off my line! Since then, the fish just aren't biting the same.\n\nFind Gammerita and get my lure out of her stomach.", progress = "Did you get it yet?", completion = "MON! This is fantastic! With my best lure and the snapjaw population down, the fish will pile up.", objectives = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.\n\nKatoom mentioned that Gammerita hangs out on the coast with the other turtles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7817] = { id = 7817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Mageweave", progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Undercity, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, {name}!" }
