quests[8041] = { id = 8041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of Mount Mugamba", sourceObjective = "Hail, {class}. I am Jin'rokh the Breaker, troll of Mugamba. We of the Zandalar tribe recognize your accomplishments. We salute your tenacity and strength of will.\n\nWear this talisman around your neck, {class}. Let the strength of Mount Mugamba flow through your being. Be empowered as you strike down our enemies!", sourceObjectiveStatus = "unverified-source-field" }
quests[8042] = { id = 8042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of Mount Mugamba", progress = "It is good to see you in good health, {name}. The glorious battles you have undertaken affect all life on this planet. Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.\n\nGive me your talisman and I shall amplify its strength. Use the Strength of Mugamba to punish our enemies!", completion = "Our paths will cross again, {class}." }
quests[8043] = { id = 8043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of Mount Mugamba", progress = "Master {name}, you return! Molthor has sent word of your deeds to the King. Your name is known even in the South Seas. Perhaps one day you will be a legendary {class} - a story for the ages.\n\nGive me your talisman so that I may once more amplify its power.", completion = "Use your newfound strength to destroy the Gurubashi!" }
quests[8044] = { id = 8044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rage of Mugamba", progress = "King Rastakhan sends his regards, Master {name}. Such an honor has never been given to one outside the Zandalar tribe.\n\n\n\nGive me your talisman so that I may enhance it once more. Know that the Rage of Mugamba is now intrinsically connected to your very soul.", completion = "Zul'jin would be envious, {class}. Go forth and conquer!" }
quests[8045] = { id = 8045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heathen's Brand", sourceObjective = "Know this, heathen: A catastrophe has brought us together. Your pagan ways are neither understood nor appreciated by Zandalar but we are a fair people. Wear this brand around your neck. It shall serve as both a warning to our enemies and a symbol of your friendship to Zandalar.\n\nContinue to serve our people and I will amplify the power of the brand.", sourceObjectiveStatus = "unverified-source-field" }
quests[8046] = { id = 8046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heathen's Brand", progress = "I may have been too hasty in my judgement, {class}. It seems as if your blind faith in this Light has some value after all.\n\nGive me your brand and I shall amplify its power.", completion = "Do what you must to defeat our enemies, {class}. Even if it means channeling the Light.\n\n<Jin'rokh shudders.>" }
quests[8047] = { id = 8047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heathen's Brand", progress = "I must confess, I did not think you had the resolution to see this cause through, {class}. Zandalar now considers you an invaluable ally. Well done, indeed.\n\nGive me your brand and I shall once more amplify its power.", completion = "Our beliefs differ but our cause is righteous. Strike down our foes, noble {class}." }
quests[8048] = { id = 8048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero's Brand", progress = "The King has acknowledged your existence, {class}. You are the first of your kind to be accepted by Rastakhan as a true ally of Zandalar.\n\nYou will be rewarded greatly for your efforts. Present your brand and I shall apply the final amplification.", completion = "Vigilance, honor, loyalty, bravery... You embody all of these traits and so shall your brand." }
quests[8049] = { id = 8049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Zuldazar", sourceObjective = "Accept this talisman as a token of our appreciation, {class}.\n\nThe Eye of Zuldazar will grow in power as your bond with the trolls of Zandalar strengthens. Return to me periodically and I shall imbue the jewel.", sourceObjectiveStatus = "unverified-source-field" }
quests[8050] = { id = 8050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Zuldazar", progress = "Tales of your battles against the Gurubashi are whispered in the winds, priestess. Even royalty is beginning to talk of your deeds. It is rumored that King Rastakhan even mentioned you by name.\n\nThe time has come to imbue the Eye. Hand me the talisman and I shall perform the service.", completion = "Be resolute in your endeavors, {name}. The Soulflayer will attempt to siphon your will to live." }
quests[8051] = { id = 8051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Zuldazar", progress = "Welcome {class}. The Eye of Zuldazar pulses with energy. You are ready to take the next step. Hand me the talisman and I shall perform the imbue.", completion = "Continue in your battle against the Soulflayer and his minions, {name}. He must never be permitted to leave the confines of Zul'Gurub." }
quests[8052] = { id = 8052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The All-Seeing Eye of Zuldazar", progress = "If only we had ten-thousand more like you, {name}. The armies of Hakkar would be scattered to the wind in the blink of an eye.\n\n\n\nAlas, the Eye is ready to realize its full potential. Give it to me.", completion = "Smite them all and let Hakkar sort them out..." }
